def valid(number):
    number = number.replace(" ", "")
    if len(number) < 2 or any(c < "0" or c > "9" for c in number):
        return False

    total = 0
    for i, c in enumerate(reversed(number)):
        digit = int(c)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
